/*
 * dir_$old_add_link_entry - add a soft link to an old-format directory
 *
 * Original address: 0x00E5545C
 * Size: 384 bytes (0x00E5545C .. 0x00E555DB)
 * Generated by: Claude Opus 5.5
 *
 * Module-local routine of the OLD_DIR segment (no map symbol); its one
 * caller is DIR_$OLD_ADD_LINKU (0x00E577C8).  The link text lives in one
 * or two blocks of type 3 (0x90 bytes each, from block+0x370); the entry
 * itself is a type-3 slot whose UID field holds the dir_$old_link_refs_t
 * {text_len, block1, block2, 0}.
 *
 * Frame: (0x8,A6) dir_uid, (0xC,A6) handle (A2), (0x10,A6) name, (0x14,A6)
 * name_len, (0x16,A6) target (A3), (0x1A,A6) target_len (D5), (0x1C,A6)
 * replace_flag byte, (0x1E,A6) result, (0x22,A6) status_ret (A4).
 * Locals: A6-0x18 block1, A6-0x16 block2, A6-0x10 the link record.
 *
 * Blocks:
 *   0x00E55474-0x00E554AA  block2 = 0; block1 = dir_$old_alloc_block; none
 *                          and replace mode: D4 = target_len mod buckets,
 *                          block1 = dir_$old_reclaim_block(handle, D4);
 *                          still none -> status_$directory_is_full
 *   0x00E554AC-0x00E554DA  block1 type 3; copy the text into it, at most
 *                          0x90 bytes
 *   0x00E554DE-0x00E55516  text longer than 0x90: block2 the same way
 *                          (reclaim hint D4 + 1 mod buckets); none -> free
 *                          block1 with dir_$old_free_slot(handle, 0,
 *                          block1) and status_$directory_is_full
 *   0x00E5552E-0x00E5556C  block2 type 3; the text from byte 0x90 on
 *   0x00E55570-0x00E555AA  dir_$old_add_entry(dir_uid, handle, name,
 *                          name_len, 3, &rec, replace_flag, result,
 *                          status_ret)
 *   0x00E555AE-0x00E555CE  failure: free block1, and block2 when non-zero
 *
 * Quirks reproduced:
 *   - The first copy stores one byte past the text when it is shorter than
 *     0x90 (the `bhi' test follows the store at 0x00E554CE-0x00E554D6); the
 *     second stops exactly at the end (`beq' at 0x00E55568).
 *   - D4, the reclaim hint for block2, is only set when block1 itself came
 *     from dir_$old_reclaim_block; otherwise the image adds 1 mod buckets to
 *     whatever D4 held on entry (the caller's register).  That value is not
 *     reproducible in C; `hint' starts at 0 here.  The hint only chooses
 *     where the reclaim search starts.
 *   - dir_$old_reclaim_block and dir_$old_add_entry get reserved Pascal
 *     result words nobody reads.
 */

#include "dir/dir_internal.h"

/* `move.b #0x3,(0x36f,A0)' 0x00E554B6: the link entry's type as well */
#define OLD_LINK_ENTRY_TYPE     3

void dir_$old_add_link_entry(uid_t *dir_uid, uint32_t handle, uint8_t *name,
                             uint16_t name_len, uint8_t *target,
                             uint16_t target_len, boolean replace_flag,
                             uint8_t *result, status_$t *status_ret)
{
    uint8_t *dir = (uint8_t *)ARCH_VA_TO_PTR(handle);  /* A2 */
    uint16_t block1;                                   /* A6-0x18 */
    uint16_t block2;                                   /* A6-0x16 */
    dir_$old_link_refs_t rec;                          /* A6-0x10 */
    uint16_t hint = 0;                                 /* D4, see header */
    uint8_t *text;
    uint16_t i;                                        /* D1 */
    int16_t n;                                         /* D2 */

    /* 0x00E55474-0x00E554AA */
    block2 = 0;
    block1 = dir_$old_alloc_block(handle);
    if (block1 == 0) {
        if ((int8_t)replace_flag < 0) {
            hint = (uint16_t)((uint32_t)target_len %
                              DIR_OLD_W(dir, DIR_OLD_HDR_BUCKETS));
            block1 = dir_$old_reclaim_block(handle, hint);
        }
        if (block1 == 0) {
            *status_ret = status_$directory_is_full;
            return;
        }
    }

    /* 0x00E554AC-0x00E554DA */
    DIR_OLD_BLOCK(dir, block1)[DIR_OLD_BLOCK_TYPE] = DIR_OLD_BLOCK_LINK_TEXT;
    text = DIR_OLD_BLOCK(dir, block1) + DIR_OLD_BLOCK_TEXT;
    n = DIR_OLD_BLOCK_TEXT_MAX - 1;
    i = 1;
    do {                                                /* dbf D2w */
        text[i - 1] = target[i - 1];
        if (i > target_len) {
            break;
        }
        i++;
    } while (n-- != 0);

    if (target_len > DIR_OLD_BLOCK_TEXT_MAX) {
        /* 0x00E554E6-0x00E55516 */
        block2 = dir_$old_alloc_block(handle);
        if (block2 == 0) {
            if ((int8_t)replace_flag < 0) {
                hint = (uint16_t)(hint +
                                  (uint16_t)(1u % DIR_OLD_W(dir, DIR_OLD_HDR_BUCKETS)));
                block2 = dir_$old_reclaim_block(handle, hint);
            }
            if (block2 == 0) {
                dir_$old_free_slot(handle, 0, block1);
                *status_ret = status_$directory_is_full;
                return;
            }
        }

        /* 0x00E5552E-0x00E5556C */
        DIR_OLD_BLOCK(dir, block2)[DIR_OLD_BLOCK_TYPE] = DIR_OLD_BLOCK_LINK_TEXT;
        text = DIR_OLD_BLOCK(dir, block2) + DIR_OLD_BLOCK_TEXT;
        n = DIR_OLD_BLOCK_TEXT_MAX - 1;
        i = 1;
        do {                                            /* dbf D2w */
            text[i - 1] = target[DIR_OLD_BLOCK_TEXT_MAX + i - 1];
            if ((uint32_t)target_len == (uint32_t)i + DIR_OLD_BLOCK_TEXT_MAX) {
                break;
            }
            i++;
        } while (n-- != 0);
    }

    /* 0x00E55570-0x00E555AA */
    rec.text_len = target_len;
    rec.block1 = block1;
    rec.block2 = block2;
    rec.reserved_06 = 0;
    dir_$old_add_entry(dir_uid, handle, name, name_len, OLD_LINK_ENTRY_TYPE,
                       &rec, replace_flag, result, status_ret);

    /* 0x00E555AE-0x00E555CE */
    if (*status_ret != status_$ok) {
        dir_$old_free_slot(handle, 0, block1);
        if (block2 != 0) {
            dir_$old_free_slot(handle, 0, block2);
        }
    }
}
